contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and amounts for deposit and collect
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // Keep values in wide admissible domain
        vm.assume(depositor != address(0));
        depositAmt = bound(depositAmt, 0, 10 ether);
        collectAmt = bound(collectAmt, 0, 10 ether);

        // Give depositor enough ETH to deposit
        vm.deal(depositor, depositAmt + 1 ether);

        // Make depositor perform Deposit with depositAmt
        vm.prank(depositor);
        if (depositAmt > 0) {
            c.Deposit{value: depositAmt}();
        } else {
            // still call Deposit with zero value to exercise path
            vm.prank(depositor);
            c.Deposit{value: 0}();
        }

        // Record balance mapping for depositor before Collect
        uint256 before = c.balances(depositor);

        // Attempt Collect(collectAmt) as depositor, capture success/failure
        bool ok;
        vm.prank(depositor);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect, the reference contract always ensures that if Collect succeeded
        // then balances[depositor] == before - collectAmt (and if Collect failed then balances unchanged).
        // We assert that either Collect reverted (ok==false) and balances unchanged, or it succeeded and
        // balances decreased by collectAmt. This is a universal property the reference satisfies; the mutant
        // which credited address(0) on Deposit can cause ok==true but balances[depositor] unchanged, so the
        // assertion will fail for some fuzz inputs.
        uint256 after = c.balances(depositor);

        bool cond;
        if (!ok) {
            cond = (after == before);
        } else {
            // ensure no underflow in expectation: Collect only succeeds when before>=MinSum and before>=collectAmt
            // but we do not call MinSum here; still check arithmetic safely
            if (before >= collectAmt) {
                cond = (after == before - collectAmt);
            } else {
                // If Collect erroneously succeeded despite insufficient balance, fail the test (contract shouldn't allow)
                cond = false;
            }
        }

        assertTrue(cond);
    }
}

