        // keep depositor non-zero to avoid trivial address(0) interactions and make it a sane EOA
        vm.assume(depositor != address(0));
        // bound amounts to avoid overflow issues and extremely large values
        depositAmt = bound(depositAmt, 1 wei, 1 ether * 1000);
        collectAmt = bound(collectAmt, 0 wei, 1 ether * 1000);

