        vm.deal(depositor, depositAmt + collectAmt + 1 ether);

        // make depositor perform Deposit
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // compute a conservative sample of total stored balances by probing several addresses likely to be relevant
        // Since we cannot iterate mapping, we sample: depositor and address(0) are the only keys implicated by reference vs mutant
        uint256 totalBefore = c.balances(depositor) + c.balances(address(0));

        // depositor attempts to Collect collectAmt
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful Collect, the total stored sum at those two keys should decrease by exactly collectAmt in the reference.
