contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract and assert the invariant distinguishing P from M.
    // Inputs:
    //  newMin: a candidate new MinSum to try setting after initialization
    // The test calls SetMinSum before initialization to establish a baseline,
    // then calls Initialized(), then attempts to call SetMinSum again and
    // finally asserts that MinSum remained the same as the value observed
    // right after initialization (i.e., SetMinSum had no effect after init).
    function run(uint newMin) public {
        // set MinSum once (allowed before initialization)
        c.SetMinSum(newMin);

        // record MinSum observed after the allowed setting
        uint observed = c.MinSum();

        // mark the contract initialized — after this, P forbids changes to MinSum
        c.Initialized();

        // attempt to change MinSum again (in P this will revert; in M it will succeed)
        // We perform the call and capture whether it succeeded.
        bool ok;
        (ok,) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMin + 1);

        // read current MinSum
        uint after = c.MinSum();

        // If contract P is in use, either the second SetMinSum reverted (ok==false)
        // and MinSum stayed equal to observed, or if it returned ok==true (shouldn't happen in P),
        // the value would have changed. We assert the general rule: after initialization
        // the stored MinSum equals the observed value.
        assert(after == observed);
    }

    // Allow the test contract to receive ETH if needed by caller
    receive() external payable {}
}

